// Verification host only. String copying, allocation and collection execute MASM.
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
public static class BoomCharsProbe {
    [StructLayout(LayoutKind.Sequential)] struct Context { public uint Kind,PC,Method,Depth; }
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode)] static extern IntPtr LoadLibraryExW(string p,IntPtr z,uint f);
    [DllImport("kernel32.dll",CharSet=CharSet.Ansi)] static extern IntPtr GetProcAddress(IntPtr m,string n);
    [DllImport("kernel32.dll")] static extern bool FreeLibrary(IntPtr m);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Create(ulong n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Bind(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Destroy(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Get();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Roots(out uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Collect(IntPtr h,IntPtr roots,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Alloc(IntPtr h,ulong bytes,uint refs,uint type);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Entry(ref Context c,[In] ulong[] a);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Service(ref Context c,[In] ulong[] a,IntPtr pool);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr RawService(IntPtr c,[In] ulong[] a,IntPtr pool);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint Release();
    static void Check(bool ok,string s){if(!ok)throw new Exception(s);}
    static IntPtr Open(string p){IntPtr m=LoadLibraryExW(p,IntPtr.Zero,0x1100);Check(m!=IntPtr.Zero,"Char module load failed");return m;}
    static T Fn<T>(IntPtr m,string n){IntPtr p=GetProcAddress(m,n);Check(p!=IntPtr.Zero,"Missing "+n);return Marshal.GetDelegateForFunctionPointer<T>(p);}
    static void Close(IntPtr m,IntPtr h){IntPtr p=GetProcAddress(m,"boom_release_trace_pool");if(p!=IntPtr.Zero)Check(Marshal.GetDelegateForFunctionPointer<Release>(p)()==0,"Char frames active");if(h!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(h)!=0,"Char heap cleanup failed");FreeLibrary(m);}
    static IntPtr Invoke(Entry e,params ulong[] a){var c=new Context();ulong v=e(ref c,a);Check(v!=0&&c.Kind==0&&c.Depth==0,"Char source entry failed: "+c.Kind);return new IntPtr(unchecked((long)v));}
    static ulong Bits(IntPtr p){return unchecked((ulong)p.ToInt64());}
    static string ArrayText(IntPtr p){Check(p!=IntPtr.Zero&&Marshal.ReadInt64(p,-8)==261&&Marshal.ReadInt32(p,-20)==0,"Malformed copied char[]");long n=Marshal.ReadInt64(p,-16);Check(n>=0&&(n&1)==0&&n<=131072,"Malformed copied char[] length");return Marshal.PtrToStringUni(p,checked((int)n/2));}
    static int Reachable(IntPtr roots,uint n){var seen=new HashSet<IntPtr>();var todo=new Stack<IntPtr>();for(int i=0;i<n;i++)todo.Push(Marshal.ReadIntPtr(roots,i*8));while(todo.Count!=0){IntPtr p=todo.Pop();if(p==IntPtr.Zero||!seen.Add(p))continue;uint f=unchecked((uint)Marshal.ReadInt32(p,-24)),refs=unchecked((uint)Marshal.ReadInt32(p,-20));long bytes=Marshal.ReadInt64(p,-16);Check((f&0xfffffffd)==0xb00b0001&&bytes>=0&&refs<=(ulong)bytes/8&&seen.Count<1048576,"Malformed char graph");for(int i=0;i<refs;i++)todo.Push(Marshal.ReadIntPtr(p,i*8));}return seen.Count;}
    static void GC(IntPtr m,IntPtr h,params IntPtr[] extra){IntPtr roots=Fn<Roots>(m,"boom_get_static_roots")(out uint n),all=Marshal.AllocHGlobal(checked(((int)n+extra.Length)*8));try{for(int i=0;i<n;i++)Marshal.WriteIntPtr(all,i*8,Marshal.ReadIntPtr(roots,i*8));for(int i=0;i<extra.Length;i++)Marshal.WriteIntPtr(all,((int)n+i)*8,extra[i]);uint count=checked(n+(uint)extra.Length);int live=Reachable(all,count);Check(Fn<Collect>(m,"boom_heap_collect")(h,all,count)!=ulong.MaxValue&&Marshal.ReadInt64(h,56)==live,"Char GC root graph mismatch");}finally{Marshal.FreeHGlobal(all);}}
    static IntPtr Copy(Service f,IntPtr pool,IntPtr s){var c=new Context();IntPtr p=f(ref c,new ulong[]{Bits(s)},pool);Check(p!=IntPtr.Zero&&c.Kind==0,"Native char copy failed: "+c.Kind);return p;}
    public static string[] Raw(string dll,string[] cases){IntPtr m=Open(dll),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(4*1024*1024);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Raw char heap failed");var e=Fn<Entry>(m,"boom_entry");var output=new string[cases.Length];for(int i=0;i<cases.Length;i++){string[] a=cases[i].Split(' ');IntPtr p=Invoke(e,Convert.ToUInt32(a[0],16),Convert.ToUInt32(a[1],16));var hex=new StringBuilder();foreach(char c in ArrayText(p))hex.Append(((int)c).ToString("x4"));output[i]=hex.ToString();GC(m,h);}return output;}finally{Close(m,h);}}
    public static void Objects(string dll,string runtime){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(65536);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Char object heap failed");var e=Fn<Entry>(m,"boom_entry");var f=Fn<Service>(m,"boom_string_to_chars");IntPtr pool=Fn<Get>(m,"boom_get_chars_string_pool")();var source=new IntPtr[8];for(uint i=0;i<8;i++)source[i]=Invoke(e,i);GC(m,h);long baseline=Marshal.ReadInt64(h,56);
        for(int i=0;i<256;i++){IntPtr s=source[i&7],backing=Marshal.ReadIntPtr(s);string original=ArrayText(backing);long count=Marshal.ReadInt64(h,56);IntPtr a=Copy(f,pool,s),b=Copy(f,pool,s);Check(a!=b&&a!=backing&&b!=backing&&ArrayText(a)==original&&ArrayText(b)==original&&Marshal.ReadInt64(h,56)==count+2,"Copy identity/one-allocation budget failed");if(original.Length!=0){Marshal.WriteInt16(a,0,unchecked((short)0xbeef));Check(ArrayText(backing)==original&&ArrayText(b)==original,"Copied array aliases immutable backing");}GC(m,h,a,b);Check(ArrayText(b)==original,"Copied char[] lost after GC");GC(m,h);}
        var c=new Context{Kind=9,PC=17,Method=23,Depth=3};Check(f(ref c,new ulong[]{0},IntPtr.Zero)==IntPtr.Zero&&c.Kind==9&&c.PC==17&&c.Method==23&&c.Depth==3,"Copy changed pending exception");c=new Context{PC=17,Method=23};Check(f(ref c,new ulong[]{0},pool)==IntPtr.Zero&&c.Kind==4&&c.PC==17&&c.Method==23,"Copy null exception incorrect");Check(Fn<RawService>(m,"boom_string_to_chars")(IntPtr.Zero,new ulong[]{Bits(source[1])},pool)==IntPtr.Zero,"Copy accepted absent context");
        IntPtr copy=Marshal.AllocHGlobal(80);try{byte[] data=new byte[80];Marshal.Copy(pool,data,0,80);foreach(int off in new[]{0,4,16,40,48,64}){Marshal.Copy(data,0,copy,80);if(off<24)Marshal.WriteInt32(copy,off,off==16?65537:7);else Marshal.WriteIntPtr(copy,off,IntPtr.Zero);c=new Context();Check(f(ref c,new ulong[]{Bits(source[1])},copy)==IntPtr.Zero&&c.Kind==7,"Copy accepted malformed pool: "+off);}IntPtr foreign=Fn<Create>(m,"boom_heap_create")(65536);Check(foreign!=IntPtr.Zero,"Char foreign heap failed");try{Marshal.Copy(data,0,copy,80);Marshal.WriteIntPtr(copy,48,foreign);c=new Context();Check(f(ref c,new ulong[]{Bits(source[1])},copy)==IntPtr.Zero&&c.Kind==7,"Copy accepted foreign heap");}finally{Check(Fn<Destroy>(m,"boom_heap_destroy")(foreign)!=0,"Foreign cleanup failed");}}finally{Marshal.FreeHGlobal(copy);}
        IntPtr chars=Marshal.ReadIntPtr(source[1]);foreach(int off in new[]{-32,-24,-20,-16,-8}){long old=Marshal.ReadInt64(chars,off);try{Marshal.WriteInt64(chars,off,off==-32?long.MaxValue:7);c=new Context();Check(f(ref c,new ulong[]{Bits(source[1])},pool)==IntPtr.Zero&&c.Kind==7,"Copy accepted malformed array header: "+off);}finally{Marshal.WriteInt64(chars,off,old);}}
        Check(Marshal.ReadInt64(h,56)==baseline,"Copy metadata/exception gates allocated");GC(m,h);
    }finally{Close(m,h);FreeLibrary(r);}}
    public static void Tail(string dll,string runtime){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(65536);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Char tail heap failed");IntPtr s=Invoke(Fn<Entry>(m,"boom_entry"),0),pool=Fn<Get>(m,"boom_get_chars_string_pool")();GC(m,h);var alloc=Fn<Alloc>(r,"boom_heap_alloc");Check(alloc(h,64,0,267)!=IntPtr.Zero,"Char tail hole failed");long left=Marshal.ReadInt64(h,16)-Marshal.ReadInt64(h,48);if((left&31)!=0)Check(alloc(h,16,0,267)!=IntPtr.Zero,"Char tail alignment failed");var fillers=new List<IntPtr>();IntPtr last=IntPtr.Zero,v;while((v=alloc(h,0,0,261))!=IntPtr.Zero){last=v;fillers.Add(v);}Check(last!=IntPtr.Zero&&last==Marshal.ReadIntPtr(h,24),"Empty backing not at arena end");Marshal.WriteIntPtr(s,last);GC(m,h,fillers.ToArray());long count=Marshal.ReadInt64(h,56);IntPtr a=Copy(Fn<Service>(m,"boom_string_to_chars"),pool,s);Check(a!=last&&ArrayText(a)==""&&Marshal.ReadInt64(h,56)==count+1,"Tail empty copy failed");GC(m,h,a);Check(ArrayText(Marshal.ReadIntPtr(s))==""&&ArrayText(a)=="","Tail empty roots lost");}finally{Close(m,h);FreeLibrary(r);}}
    public static void FullHeap(string dll,string runtime){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(65536);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Char full heap failed");var e=Fn<Entry>(m,"boom_entry");for(uint i=0;i<8;i++)Invoke(e,i);GC(m,h);var alloc=Fn<Alloc>(r,"boom_heap_alloc");while(alloc(h,4096,0,267)!=IntPtr.Zero){}while(alloc(h,0,0,267)!=IntPtr.Zero){}long full=Marshal.ReadInt64(h,56);for(uint i=0;i<256;i++){var c=new Context();Check(e(ref c,new ulong[]{i})==97&&c.Kind==0&&c.Depth==0&&Marshal.ReadInt64(h,56)==full,"Full heap copy OOM not caught, including empty");}GC(m,h);var ok=new Context();Check(e(ref ok,new ulong[]{1})==24&&ok.Kind==0,"Char OOM recovery failed");GC(m,h);}finally{Close(m,h);FreeLibrary(r);}}
}
